$string['copykoha'] = "To move to Koha, the free library program.\n\ncatalogo.mrc: the records in MARC 21 with their copies in field 952. It goes into «Tools > Stage MARC records for import», and when importing you tell it to add the items.\n\nlectores.csv: the readers, in Koha's «Import patrons», with their cards. First create in Koha the library (the code in the branchcode column, also in \$a and \$b of each 952) and the categories ST, T, S and PT; and the item types BK and REF.\n\nprestamos.koc: the books that are out, in «Circulation > Upload offline circulation file». It goes last, with the readers and copies already in.";
$string['copymade'] = 'Copy made.';
$string['copymake'] = 'Make a copy now';
$string['copyreadme'] = "Copy of the libraries of {\$a->entity}, made on {\$a->date} by Oksigenia Ayvurenda {\$a->release}.\n\nEach CSV file is one table, with its column names in the first row. They open in any spreadsheet.\n\n- entity, library: the entity and its libraries.\n- record, authority, recauth: the catalogue (titles, authors, subjects…).\n- item: the copies and material, with their barcodes.\n- reader, member: the readers and their group each academic year.\n- loan: the loans, out and returned.\n- hold: reservations, waiting, set aside and over.\n- stocktake, stockread: the stocktakes and what was read in each.\n- withdrawal, withdrawn: the records of weeding and their copies.\n- lot, lotitem: the boxes lent between libraries and their copies.\n- digital: the digital forms of the records (without their files, which stay in the site).\n- rule, year, tutor, source: loan rules, academic years, tutors and where each row came from.\n- catalogo.mrc and catalogo.xml: the catalogue in MARC21 (ISO 2709 and MARCXML), with its copies in field 852, to take it to any library program.\n- catalogo-dc.xml: the catalogue in Dublin Core, for repositories and catalogues that do not read MARC.\n- catalogo.ris: the catalogue in RIS, for reference managers such as Zotero or Mendeley.\n- challenge, wish: the challenges of the classes and what they asked for.\n- review, roomread: the reviews and what was read in the room.\n- bankset, banktitle: the sets of the textbook bank and their titles.\n- koha/: the same, ready to go to Koha (see its LEEME).\n\nCovers and the digital collection go in another copy, the one of the files. Recorded voices do not leave the server.\n\nRows in each file:\n{\$a->counts}\n";
