$string['helpadd01'] = 'To add new books, read the book\'s code: the ISBN, the one starting with 978 or 979.';
$string['helpadd02'] = 'Ayvurenda looks it up in the catalogues and shows you its card. In this practice, in a made-up catalogue.';
