$string['helpbank01'] = 'A set is what each pupil of some groups is lent: its titles and the groups it is for.';
$string['helpbank02'] = 'Each title says how many copies are out and how many are free; if there are not enough for everyone, it says so in red.';
$string['helpbank03'] = 'To add a title to the set, look for it by its name or its ISBN.';
$string['helpbank04'] = 'A new set: its name and the groups that take it. Every pupil of those groups waits for all its titles.';
$string['helpbank05'] = 'By class: each class, with who waits for books and who has them.';
$string['helpbank06'] = 'In a class, each pupil with what they have and what they lack. At the desk, their set comes up with their card, with the contract for the family.';
$string['helpbankround01'] = 'This is where you run the end-of-year collecting: how many books are still out and how many are back.';
$string['helpbankround02'] = 'Set the deadline. The reminders will say it.';
$string['helpbankround03'] = 'With one touch, each reader gets a reminder with their books, and each tutor, who in their class has them. At most once a day.';
$string['helpbankround04'] = 'Each class, with what it has out. Go into one to see who has what.';
$string['helpbankround05'] = 'If a book does not come back, note it as lost. The bank charges nothing: it says what is missing and from whom.';
$string['helpbankround06'] = 'If it turns up, one touch puts it back on the shelf.';
$string['helpbankround07'] = 'And when the year starts, the handing out: who is waiting for books and how many copies each set is short of.';
$string['helpbankround08'] = 'Each class has its list and its contracts, to print and for the families to sign.';
$string['helpcard01'] = 'This is a reader\'s card, as they see it: on the phone, in the classroom or on the library\'s computer.';
$string['helpcard02'] = 'Their flower grows with what happens at the desk: coming back, exploring new corners, telling what they thought of a book and finishing what they start. It never withers.';
$string['helpcard03'] = 'The card\'s code goes through the desk like a book: with the scanner, the camera or the phone.';
$string['helpcard04'] = 'Here they see which paths it grows by, with no numbers and no comparing with anyone.';
$string['helpcard05'] = 'From twelve on the sky comes instead of the flower, and everyone can choose the classic look. You can see it as they would.';
$string['helpcard06'] = 'This is how a secondary school reader sees it: the same card, another look.';
$string['helpcard07'] = 'To print them, «Print cards» in Readers: for the whole centre, a stage or a class, each with its design.';
$string['helpcardprint01'] = 'First, whose: all the readers or some of them. A single reader is printed from their record.';
$string['helpcardprint02'] = 'The design of each card, by the age of whoever carries it. «Change it» sets one for all, or a different one by age.';
$string['helpcardprint03'] = 'The logo goes at the top right of every card.';
$string['helpcardprint04'] = 'Where they are printed: at a print shop, on plastic cards, on card sheets or on plain paper. Each way makes the PDF to its size.';
$string['helpcardprint05'] = 'What the back says: the address and a few lines of the library, the same on all of them.';
$string['helpcardprint06'] = 'And «Prepare». If they are few, they download at once; if many, they are prepared apart and appear under «Ready».';
$string['helpdesk01'] = 'This is the desk: one field, always ready. The scanner types into it by itself, and you can type too.';
$string['helpdesk02'] = 'Ana comes with a book. First, her card.';
$string['helpdesk03'] = 'Her card opens: what she has at home and whether something is late.';
$string['helpdesk04'] = 'Now the book. It is lent, with its return date, and a short tone sounds.';
$string['helpdesk05'] = 'If you made a mistake, «Undo» leaves it as it was.';
$string['helpdesk06'] = 'Noa brings a book back. To give it back, read the book: no card needed.';
$string['helpdesk07'] = 'It is late: the desk says so and takes it back all the same.';
$string['helpdesk08'] = 'On return, a note of one tap: loved it, did not finish it or wants more like it.';
$string['helpdesk09'] = 'Noa wants more books like this one: tap «Wants more like it».';
$string['helpdesk10'] = 'That is all. What is lent, given back and noted reaches the notices and the numbers of the year.';
$string['helpdesk10lay'] = 'That is all. What is lent, given back and noted reaches the notices and the numbers of the year.';
$string['helpdone'] = 'Done.';
$string['helpdoneadd'] = 'You know how to add a box of new books.';
$string['helpdonebank'] = 'Now you know how to make the sets and see each class.';
$string['helpdonebankround'] = 'Now you know how to run the collecting and the handing out.';
$string['helpdonecard'] = 'Now you know what the card is like and how each reader sees it.';
$string['helpdonecardprint'] = 'Now you know how to print the cards.';
$string['helpdonedesk'] = 'You know how to lend, take back and note at the desk.';
$string['helpdoneformats'] = 'You now know how to give a book in another format.';
$string['helpdonefree'] = 'Now you can look for a work on the real page and bring it.';
$string['helpdoneholds'] = 'You can look after the holds of your library now.';
$string['helpdoneill'] = 'Now you can keep track of lending with other libraries.';
$string['helpdoneimport'] = 'You can bring your file now: nothing comes in until you confirm it.';
$string['helpdonekeepers'] = 'Now you can choose who keeps each library from its card.';
$string['helpdonelabels'] = 'Now you know how to print the labels and spine labels of new books.';
$string['helpdonelate'] = 'You can look at the late books of your library now.';
$string['helpdonematerial'] = 'Now you can add your own material.';
$string['helpdonemyclass'] = 'Now you know how to choose your class\'s challenge and the book it earns when it meets it.';
$string['helpdonepurchases'] = 'Now you can keep track of your purchases.';
$string['helpdonereaders'] = 'You can bring your readers now.';
$string['helpdonereaderslist'] = 'You can load your list now: nobody arrives until you confirm it.';
$string['helpdonerecord'] = 'Now you know how to correct a record and its copies.';
$string['helpdonereports'] = 'Now you know where the reports are and how to take them with you.';
$string['helpdonereviews'] = 'Now you know how to publish what readers tell.';
$string['helpdonerules'] = 'You can adjust the rules of your library now.';
$string['helpdonesanctions'] = 'You can now decide what a book that comes back late leaves.';
$string['helpdoneselfloan'] = 'Now you can make your post.';
$string['helpdonestacks'] = 'You know how to walk along the shelves and how to find a book on the real ones.';
$string['helpdonetutors'] = 'Now you can set the tutors of your groups.';
$string['helpdonetwins'] = 'Now you can go through your repeated readers.';
$string['helpdonevoices'] = 'You can approve the voices waiting in your library now.';
$string['helpdoneweed'] = 'You can review your collection now: nothing leaves until you mark it and confirm it.';
$string['helpdonewishes'] = 'Now you know what to do with the book a class chooses.';
$string['helpformats01'] = 'Here come the books a reader asks for in another format: large print, audio, braille or digital text. They do not need to say why.';
$string['helpformats02'] = 'If you have it, press «They have it» and choose how they get it: from the digital collection, if it is there as an accessible format, or some other way, on paper or by hand.';
$string['helpformats03'] = 'save, and they are told.';
$string['helpformats04'] = '«Done» keeps what was given and what could not be done.';
$string['helpformats05'] = 'On a reader\'s record you can mark that they need accessible formats: they will see the ones in the digital collection marked that way, and nobody else will.';
$string['helpframe'] = 'The screen, in practice';
$string['helpfree01'] = 'Two sources of works in the public domain: Project Gutenberg, with a great deal in English, and Wikisource, with many works in Spanish and other languages.';
$string['helpfree02'] = 'Type a title or an author, and search.';
$string['helpfree03'] = 'Choose a work: you see who wrote it and what its rights say.';
$string['helpfree04'] = 'Tick who it is for, and that it is in the public domain in your country too: each country counts from when the author died.';
$string['helpfree05'] = '«Bring it into the catalogue», and it stays with its record and its book, to be read here in the library. A long work takes a moment.';
$string['helpholds01'] = 'At the top, what is set aside: the book is at the desk, waiting for its reader until that date.';
$string['helpholds02'] = 'Below, the queue: who is waiting for each book, and how many are ahead of them.';
$string['helpholds03'] = 'When the book comes back, the desk tells you as you return it: it is set aside, and its reader gets the notice.';
$string['helpholds04'] = '«Cancel» takes someone out of the queue, or frees what was set aside.';
$string['helpholds05'] = 'And here you decide how holds are placed: at the desk, always; online, if you want and for whom you want.';
$string['helpill01'] = 'When a book is not here and another library has it, you keep track here: what you ask for and what you lend.';
$string['helpill02'] = 'The title, which library you ask and, if it is for someone, their card.';
$string['helpill03'] = 'note it with «Ask for a book».';
$string['helpill04'] = 'When it comes, mark it, with the date it has to go back. Whoever is waiting gets a notice.';
$string['helpill05'] = 'And if another library asks you for one, you lend it from here. When it comes back, you scan it at the desk.';
$string['helpimport01'] = 'Your catalogue comes in here: a MARC file from the program you use now, or a spreadsheet saved as CSV.';
$string['helpimport02'] = 'You drop it here, or choose it, and it moves on to the next step by itself. Nothing has come in yet.';
$string['helpimport03'] = 'First, the figures of the whole file: titles, copies, places, and those arriving without a code.';
$string['helpimport04'] = 'And the first books, standing on their shelf with their spine label: this is how they will look.';
$string['helpimport05'] = 'Each column is recognised by its name. One that is not recognised stays out of the way.';
$string['helpimport06'] = 'If one was taken wrongly, you correct it here, seeing what each one says, and the shelf is drawn again.';
$string['helpimport07'] = 'when it looks right, import it.';
$string['helpimport08'] = 'It is in. If you import the same file again, it updates what was there and repeats nothing.';
$string['helpimport09'] = 'And this is what comes next: looking at the catalogue, printing the labels, bringing the readers and opening the desk.';
$string['helpintroadd'] = 'A minute to add books by their ISBN, on a practice library: nothing of yours is touched.';
$string['helpintrobank'] = 'How to make a set of textbooks and see, class by class, who has what, in a practice bank.';
$string['helpintrobankround'] = 'How to run the end-of-year collecting and the next year\'s handing out, in a practice bank.';
$string['helpintrocard'] = 'A minute with the card of a made-up reader of the practice library: how they see it, what makes it grow and how it goes through the desk.';
$string['helpintrocardprint'] = 'How the cards are printed: whose, with which design and where, in the practice library.';
$string['helpintrodesk'] = 'A minute at the desk, on a practice library with made-up readers and books: nothing of yours is touched.';
$string['helpintroformats'] = 'A reader asked for a book in audio. Nothing is kept: it is the practice library.';
$string['helpintrofree'] = 'Bringing a work in the public domain into the catalogue, with its book, to be read in the library. Nothing is fetched from outside: it is the practice library.';
$string['helpintroholds'] = 'What is set aside, who is waiting and how holds are placed. It happens in the practice library, with example readers.';
$string['helpintroill'] = 'Asking another library for a book and lending it one. Nothing is saved: it is the practice library.';
$string['helpintroimport'] = 'Bringing a whole catalogue from another program. It happens in the practice library, with an example file: your catalogue is not touched.';
$string['helpintrokeepers'] = 'Choosing who keeps a library: a teacher, the class teacher or a pupil librarian, at its own desk. Nothing is saved: it is the practice library.';
$string['helpintrokeeperslay'] = 'Choosing who keeps a library, at its own desk. Nothing is saved: it is the practice library.';
$string['helpintrolabels'] = 'A minute to print labels and spine labels, with made-up books of the practice library.';
$string['helpintrolate'] = 'Who has a late book and how they are told. It happens in the practice library, with example readers: nobody is told anything.';
$string['helpintromaterial'] = 'Adding what is lent and is not a book. Nothing is saved: it is the practice library.';
$string['helpintromyclass'] = 'A minute with the tutor\'s page, with two made-up groups of the practice library.';
$string['helpintropurchases'] = 'From what readers ask for to the order to the vendor. Nothing is saved: it is the practice library.';
$string['helpintroreaders'] = 'Who is in your library, how to find one and where they come from. It happens in the practice library, with example readers.';
$string['helpintroreaderslist'] = 'Registering readers from a spreadsheet. It happens in the practice library, with an example list.';
$string['helpintrorecord'] = 'How the record of a book and its copies are corrected, in the practice library.';
$string['helpintroreports'] = 'A minute with the library\'s six reports, on the made-up loans of the practice library.';
$string['helpintroreviews'] = 'A minute to publish reviews, with two made-up ones of the practice library.';
$string['helpintrorules'] = 'How long and how many books at once, and for whom. It happens in the practice library: your rules do not change.';
$string['helpintrosanctions'] = 'Only the warning, days without lending or a fine. Nothing is kept: it is the practice library.';
$string['helpintroselfloan'] = 'Making a self-loan post and going over what is done at it. Nothing is saved: it is the practice library.';
$string['helpintrostacks'] = 'A minute along the shelves of the practice library: the spines, their labels, the gaps and the lectern.';
$string['helpintrotutors'] = 'Setting the tutor of each group. Nothing is saved: it is the practice library.';
$string['helpintrotwins'] = 'Joining two records of the same person. Nothing is saved: it is the practice library.';
$string['helpintrovoices'] = 'What to look at before others hear a recorded voice. It happens in the practice library, with an example voice.';
$string['helpintroweed'] = 'Taking out of the collection what no longer serves, with its record. It happens in the practice library: your collection does not change.';
$string['helpintrowishes'] = 'Half a minute with the book a made-up class of the practice library asked for.';
$string['helpkeepers01'] = 'Here you choose who keeps this library: a teacher of the department, the class teacher or a pupil librarian.';
$string['helpkeepers01lay'] = 'Here you choose who keeps this library: whoever looks after that room, someone of the department or a volunteer.';
$string['helpkeepers02'] = 'Look for a reader of the centre by name: they need an account.';
$string['helpkeepers03'] = '«Let them keep it», and they can work at this library\'s desk, and only there: its books and, in a classroom library, the readers of its groups.';
$string['helpkeepers03lay'] = '«Let them keep it», and they can work at this library\'s desk, and only there.';
$string['helpkeepers04'] = 'To take it away, «Take it away». The centre\'s staff go on as always.';
$string['helplabels01'] = 'Labels with the barcode for inside the book, or spine labels with its call number.';
$string['helplabels02'] = 'Choose which: those added today, those since a date or some codes.';
$string['helplabels03'] = 'For example, two books by their codes.';
$string['helplabels04'] = 'This is how they come out, on the sheet of stickers you choose.';
$string['helplabels05'] = 'If you already used part of a sheet, start at the first free square: no sticker is wasted.';
$string['helplabels06'] = 'And at the end, «Print»: better at one hundred per cent and without margins.';
$string['helplate01'] = 'What has been out the longest, first. These cards count how many there are in each span, and filter.';
$string['helplate02'] = 'Each box says how many readers it holds and how late the latest is; in red, past thirty days.';
$string['helplate03'] = 'Open it, and you see who has what.';
$string['helplate04'] = 'The name leads to their record, with everything they have.';
$string['helplate05'] = 'The list can be printed, and the button to tell someone sends the reminder now, without waiting.';
$string['helplate06'] = 'The late notices already go out by themselves every day: this is for when you want to get ahead.';
$string['helpmaterial01'] = 'What is lent and is not a book comes in here: laptops, tablets, calculators, cameras or games. First, its name.';
$string['helpmaterial02'] = 'How many there are. Each one has its own label and is lent separately.';
$string['helpmaterial03'] = 'If you need them, here go the brand, the model, the serial numbers or the labels they already have.';
$string['helpmaterial04'] = 'add them with «Add».';
$string['helpmaterial05'] = 'There they are, with their codes. At the desk they are lent like a book, and their condition is noted with a tap when they go out and when they come back.';
$string['helpmyclass01'] = '«My class» is the tutor\'s page: each term\'s challenge, the class garden and what they read, never naming anyone.';
$string['helpmyclass02'] = 'When the class meets its challenge, something is planted in its garden, and the herald tells its readers on their home.';
$string['helpmyclass03'] = 'And the reward is more reading: with your class, you choose the library\'s next book.';
$string['helpmyclass04'] = 'You send it to the library, and you will see here when it arrives.';
$string['helpmyclass05'] = 'In a group that has not met it yet, you choose this term\'s challenge: corners, telling, or everyone taking a book home. Or none.';
$string['helpmyclass06'] = 'choose «Telling» for 5º B.';
$string['helpmyclass07'] = 'Everything is measured at the desk: you note nothing down, and nobody is ever named.';
$string['helpnav'] = 'How does it work?';
$string['helpnosuch'] = 'That guided help does not exist.';
$string['helpnotplayable'] = 'This guided help shows something this library does not have.';
$string['helpnow'] = 'Now you:';
$string['helppurchases01'] = 'Here is what readers ask for: the title, and who asks.';
$string['helppurchases02'] = 'Above, what you have spent this year. The budget is there if you want it.';
$string['helppurchases03'] = 'If you are going to buy it: how many, at what price and from whom. The price is not needed.';
$string['helppurchases04'] = 'say yes with «Buy it».';
$string['helppurchases05'] = 'What you are going to buy is put together by vendor.';
$string['helppurchases06'] = 'make the order.';
$string['helppurchases07'] = 'This is the sheet of the order, to send or to print.';
$string['helppurchases08'] = 'When it comes, mark it in «Ordered». When it is added with its ISBN, whoever asked for it gets a notice.';
$string['helpreaders01'] = 'Everyone is here, in two figures: how many readers and how many groups.';
$string['helpreaders01lay'] = 'Everyone is here: how many readers the library has.';
$string['helpreaders02'] = 'To find one, their name or their card.';
$string['helpreaders03'] = 'Each stage, with its groups, and how many readers each has. Tap a group and its readers appear.';
$string['helpreaders03lay'] = 'And here they all are, sixty at a time. The name leads to their record.';
$string['helpreaders04'] = 'To have more arrive, «Bring readers».';
$string['helpreaders05'] = 'Each place they can come from, and whether it is in use: a list, your management program or your learning platform.';
$string['helpreaders05lay'] = 'Each place they can come from, and whether it is in use: a list or the accounts of this site.';
$string['helpreaders06'] = 'You can use several. What arrives every night does not need bringing by hand.';
$string['helpreaderslist01'] = 'A spreadsheet saved as CSV, one row per reader with the headings on the first. You drop it here, or paste it.';
$string['helpreaderslist02'] = 'Before anyone arrives, how many readers it brings, in how many groups, and how many with email.';
$string['helpreaderslist03'] = 'And the first ones, with their name and group.';
$string['helpreaderslist04'] = 'The columns are recognised by themselves. If one was taken wrongly, you correct it here.';
$string['helpreaderslist05'] = 'when it looks right, register them.';
$string['helpreaderslist06'] = 'They are in. If you load the list again, it updates those already there and repeats nobody.';
$string['helprecord01'] = 'On the record of a book, «Correct this record» opens all the catalogue says about it.';
$string['helprecord02'] = 'The title, the authors, one per line, the ISBN, the edition, the summary: change what is wrong.';
$string['helprecord03'] = 'As you type a topic, the ones the library already uses come up: that way there are not two nearly alike.';
$string['helprecord04'] = '«Save», and the record is corrected. Its copies stay as they were.';
$string['helprecord05'] = 'Each copy has its «Correct»: the code, the call number, the place and its notes.';
$string['helprecord06'] = 'And «Remove this copy», only for what was added by mistake. What has been lent is withdrawn in «Weeding».';
$string['helpreports01'] = 'Six fixed reports, always the same, for the end of the academic year or the staff meeting.';
$string['helpreports01lay'] = 'Six fixed reports, always the same, for the year\'s report or for whoever runs the library.';
$string['helpreports02'] = 'For the reports of a period, touch a sheet: this week, this month, a term, the year, or «Another» to go from one month to another.';
$string['helpreports03'] = 'Each row, with its number and a bar to compare it at a glance.';
$string['helpreports04'] = 'All of them download as CSV, to open with any spreadsheet.';
$string['helpreports05'] = 'And the academic year in numbers, for the end-of-year report.';
$string['helpreports05lay'] = 'And the year in numbers, for the library\'s report.';
$string['helpreviews01'] = 'This is where what readers tell about the books they took home arrives: a sentence or a drawing.';
$string['helpreviews02'] = 'Who wrote it and when. Until it is published, only the staff see it.';
$string['helpreviews03'] = '«Publish» puts it on the book\'s page, signed as the centre settings say, and only for its readers.';
$string['helpreviews04'] = 'If it should not be shown, «Do not publish»: its author can write another.';
$string['helpreviews05'] = 'publish Leo\'s.';
$string['helpreviews06'] = 'Published: it counts on the telling path of their flower. When new reviews arrive, the desk says so and Moodle tells you once a day.';
$string['helprules01'] = 'Each rule is a card: who it is for, what is lent and what happens, in one sentence.';
$string['helprules02'] = 'Each number changes with «−» and «+», and is kept at once: everything else stays as it is.';
$string['helprules03'] = 'For an exception, another card: here, for teachers.';
$string['helprules03lay'] = 'For an exception, another card: here, for the staff.';
$string['helprules04'] = 'create it.';
$string['helprules05'] = 'That makes two, and the most precise one rules: teachers by theirs, everyone else by the general one.';
$string['helprules05lay'] = 'That makes two, and the most precise one rules: the staff by theirs, everyone else by the general one.';
$string['helprules06'] = 'A loan already made keeps its date: the rule counts from the next one.';
$string['helpsanctions01'] = 'Here you decide what a book that comes back late leaves. To begin with, only the warning.';
$string['helpsanctions02'] = 'It can leave days without lending: for each day late, a while without borrowing.';
$string['helpsanctions03'] = 'Or a fine: so much a day, up to a limit. It is only written down here; it is paid at the desk.';
$string['helpsanctions04'] = 'keep the days without lending.';
$string['helpsanctions05'] = 'It is kept at once and reads as a sentence. From now on, whatever comes back late leaves it when it goes through the desk.';
$string['helpsanctions06'] = 'The desk warns you before lending, but the last word is yours: you can always lend anyway.';
$string['helpselfloan01'] = 'A post is a tablet or computer where each reader lends their own books to themselves, with their card.';
$string['helpselfloan02'] = 'Give it the name of the place where it stands.';
$string['helpselfloan03'] = 'make it with «Make the post».';
$string['helpselfloan04'] = 'This address opens the post. Open it there, without logging in with any account. It is only shown now.';
$string['helpselfloan05'] = 'Here you choose who may use it and whether books can be given back at it too.';
$string['helpselfloan06'] = 'And here you go over what was done at the posts. What is wrong, you undo.';
$string['helpskip'] = 'Skip to the end';
$string['helpstacks01'] = 'Each book is a spine, as tall and as thick as the real one, in the colour of its cover. They stand in the same order as in the library.';
$string['helpstacks02'] = 'At its foot is its label: the subject number, three letters of the author and three of the title. With it, the book is found on the real shelf.';
$string['helpstacks03'] = 'A gap is a book someone has taken home: it is away.';
$string['helpstacks04'] = 'touch a spine to take the book off the shelf.';
$string['helpstacks05'] = 'On the lectern: its cover, where it is and its label. «See the record» leads to everything else.';
$string['helpstacks06'] = '«Put it back» returns it to the shelf. With the keyboard, the arrows go along the shelf, Enter takes a book out and Escape puts it back.';
$string['helpstacks07'] = '«All the places» goes back to the places and corners of the library, to start somewhere else.';
$string['helpstart'] = 'Start';
$string['helpstuck'] = 'The help stopped at this step. Press «Start» to see it again from the beginning.';
