$string['helptutors01'] = 'Each group, with its tutor. Above, how many already have one.';
$string['helptutors02'] = 'Once a week, a group\'s tutor is told who has overdue books, without the titles, and can see «My class».';
$string['helptutors03'] = 'Touch a group\'s face: a tray opens with the teachers and staff with an account, and what each one already has. Touch the tutor\'s face and it is saved.';
$string['helptutors04'] = 'When a year starts, last year\'s are proposed: with one touch they all stay, and then you only change what has changed.';
$string['helptutors05'] = 'touch a group\'s face and choose its tutor.';
$string['helptwins01'] = 'Here are the readers who look like the same person: same name and same type. It happens when coming from another program.';
$string['helptwins02'] = 'Each record says its card and its loans. Look closely before joining them: two people can share a name.';
$string['helptwins03'] = 'The one with more history is proposed to stay. You can choose the other.';
$string['helptwins04'] = 'join them with «Join them».';
$string['helptwins05'] = 'Done: the one that stays now has the loans, the history and the holds of both. The other card stops working.';
$string['helptwins06'] = 'And if two records do not show because their names are not the same, «Join two by hand», with the codes of their cards.';
$string['helpvoice'] = 'Voice';
$string['helpvoices01'] = 'Recorded voices arrive here, before anyone else hears them.';
$string['helpvoices02'] = 'First you listen. If it is not right, «Reject and delete it».';
$string['helpvoices03'] = 'If the reader is a minor, their family has to give permission for others to hear it. You note it here.';
$string['helpvoices04'] = 'The licence says what rights the reading has.';
$string['helpvoices05'] = 'With permission, you choose who else hears it. Without it, it stays here, as this line says.';
$string['helpvoices06'] = 'The signature is what will show next to the voice. You read it here before approving.';
$string['helpvoices07'] = '«Approve it», and whoever you said can hear it now.';
$string['helpvoices08'] = 'And here, how long each voice is kept and what families may choose.';
$string['helpweed01'] = 'Weeding starts here: what is worth a look, by reason, and how many of each.';
$string['helpweed02'] = 'Lost, broken or worn, old, and those nobody has taken for years. Tap a reason, and its list appears.';
$string['helpweed03'] = 'Each book, in its place, with what you need to decide: when it last went out.';
$string['helpweed04'] = '«Refine» changes the years, sets a year of publication or looks at one place only.';
$string['helpweed05'] = 'mark one to take it out.';
$string['helpweed06'] = 'This bar counts what is marked and leads to withdrawing it.';
$string['helpweed07'] = 'A reason, for the record. Nothing is erased: it is withdrawn, and that can be undone.';
$string['helpweed08'] = 'And this is the record, to print and sign. Each book can go back to the collection from here.';
$string['helpwishes01'] = 'When a class meets its challenge, it chooses the next book with its tutor, and it arrives here.';
$string['helpwishes02'] = 'Look for it in the catalogue: maybe it is there already, or it has to be got.';
$string['helpwishes03'] = 'when you have it, «Here it is».';
$string['helpwishes04'] = 'The herald tells the class on its home. If it cannot be got, «It could not be», and the class chooses another.';
